    wrap_size = 0
    wrap_offset = 0
    logical_step = width + 1

    if wrap and n_dims == 2 and height > width + 1:
        wrap_size = (self.numel() + logical_step - 1) // logical_step - main_size
        wrap_offset = self.stride(0) * logical_step
